cd /GitPython && python -c "
from git import Repo
repo = Repo('.')

# Check diff.external
val = repo.config_reader().get_value('diff', 'external')
print('diff.external:', val)

# Try diffing
print('diff HEAD:')
try:
    result = list(repo.index.diff('HEAD'))
    print('result:', result)
    if result:
        for d in result:
            print('  patch:', d.diff[:50] if d.diff else 'None')
except Exception as e:
    print(f'Error: {type(e).__name__}: {e}')

print('diff HEAD patch (create_patch=True):')
try:
    result = list(repo.index.diff('HEAD', create_patch=True))
    print('result:', result)
    if result:
        for d in result:
            print('  patch length:', len(d.diff) if d.diff else 0)
except Exception as e:
    print(f'Error: {type(e).__name__}: {e}')
"
